        defs    4647 ($ff)	; ED59h - FF7Fh

; STUB entered from bank 62 (far_call_bank63): copies the bank bound in segment 1 (this bank) into segment 3
; and jumps to far_call_dispatch.
        ld      c,$01
        oz      Os_mgb
        ld      c,$03
        oz      Os_mpb
        jp      far_call_dispatch

; STUB used on the way back: re-binds bank 62 into segment 3, restores the registers saved on the stack, RET.
; BANK-ADDRESSING SITE 3 (patched): bank 62 is the bank before bank 63, so DEC A replaces the original AND $C0 / OR $3E. Shown here as raw bytes:
; $0E,$01 LD C,1 / $E7,$5A OS_Mgb / $78 LD A,B / $3D DEC A / $00,$00,$00 NOPs (ORIGINAL: $E6,$C0 AND $C0 / $F6,$3E OR $3E) / $47 LD B,A / $0E,$03 LD C,3 / $E7,$5D OS_Mpb / POPs / RET.
        defb    $0e,$01,$e7,$5a,$78,$3d,$00,$00
        defb    $00,$47,$0e,$03,$e7,$5d,$d1,$c1
        defb    $e1,$f1,$c9
        defs    34 ($ff)	; FF9Eh - FFBFh

frontdor:
        defp    0,0
        defp    0,0
        defp    applDor_QuickEdit & $3fff,$3f	; Pointer to first application DOR
        defb    $13	; DOR type = ROM Front DOR
        defb    $08	; DOR length
        defb    'N'	; Name section
        defb    $05	; Length of name
        defm    "APPL",0	
        defb    $ff	; DOR Terminator

