        defb    $ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
        defb    $ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
        defb    $ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
        defb    $ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
        defb    $ff,$ff,$ff,$ff,$ff
romhdr:
        defb    $20	; Low byte Card ID
        defb    $00	; High byte Card ID
        defb    $03	; 4 bit Country code
        defb    $80	; External application ($80) / OZ ROM ($81)
        defb    $08	; Size of card in 16K banks
        defb    $00	; Subtype of card
        defm    "OZ"
